      return response;
    },
    onSuccess: (response: LoginByOtpResponse) => {
      if (!response.access) {
        return;
      }
      setOtpError("");
      const tokenData: TokenData = {
        token: response.access,
        phoneNumber: phone,
        createdAt: new Date().toISOString(),
      };
      patientLogin(tokenData, redirectTo);
    },
    onError: (error: any) => {
      let message = "invalid_otp";
      if (Array.isArray(error?.cause?.errors) && error.cause.errors.length > 0) {
        const validationError = error.cause.errors.find(
          (candidate: OtpValidationError) => candidate.otp,
        );
        if (validationError?.otp) {
          message = validationError.otp;
        }
      } else if (error?.message) {
        message = error.message;
      }
      setOtpError(message);
    },
  });

  const sendOtp = useCallback(() => {
    if (!isValidPhoneNumber(phone)) {
      setPhoneError("phone_number_validation_error");
      return;
    }
    sendOtpRequest({ phone_number: phone });
  }, [phone, sendOtpRequest]);

  const resendOtp = useCallback(() => {
    setOtp("");
    setOtpError("");
    sendOtpRequest({ phone_number: phone });
  }, [phone, sendOtpRequest]);

  const verifyOtp = useCallback(() => {
    verifyOtpRequest({ phone_number: phone, otp });
  }, [otp, phone, verifyOtpRequest]);

  const changePhoneNumber = useCallback(() => {
    setIsOtpSent(false);
    setOtp("");
    setOtpError("");
    setCountdown(0);
  }, []);

  const updatePhone = useCallback((value?: string) => {
    setPhone(value ?? "");
    setPhoneError("");
  }, []);

  const updateOtp = useCallback((value: string) => {
    setOtp(value);
    setOtpError("");
  }, []);

  return {
    otpLength,
    phone,
    otp,
    isOtpSent,
    phoneError,
    otpError,
    countdown,
    isSendingOtp,
    isVerifyingOtp,
    isPhoneValid: isValidPhoneNumber(phone),
    isOtpComplete: otp.length === otpLength,
    updatePhone,
    updateOtp,
    sendOtp,
    resendOtp,
    verifyOtp,
    changePhoneNumber,
  };
}

