            <Skeleton key={index} className="h-[76px] w-full rounded-2xl" />
          ))}
        </div>
      </PatientAuthLayout>
    );
  }

  // Nothing linked to this number yet — registering is the only way forward.
  if (!patients?.length) {
    return (
