            <div className="flex flex-wrap gap-4 rounded-2xl border border-gray-200 bg-white p-4">
              <MetaField
                label={t("reported")}
                value={dayjs(report.created_date).format("DD MMM, h:mm A")}
              />
              {report.encounter?.facility?.name && (
                <MetaField
                  label={t("facility")}
                  value={report.encounter.facility.name}
                />
              )}
              {report.encounter?.patient?.name && (
                <MetaField
                  label={t("patient")}
                  value={report.encounter.patient.name}
                />
              )}
            </div>

            {flags > 0 && (
              <Badge variant="yellow" className="self-start">
                {t("patient_records__flagged_count", { count: flags })}
              </Badge>
            )}

            {observations.length > 0 && (
              <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white">
                <div className="grid grid-cols-[1.5fr_0.9fr_1fr] gap-2 border-b border-gray-200 bg-gray-50 px-3.5 py-2.5">
                  <span className="text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("test")}
                  </span>
                  <span className="text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("result")}
                  </span>
                  <span className="text-right text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("patient_records__reference")}
                  </span>
                </div>
                {observations.map((observation) => {
                  const flagged = isObservationFlagged(observation);
                  const reference = referenceRangeLabel(observation);
                  return (
                    <div
                      key={observation.id}
                      className="grid grid-cols-[1.5fr_0.9fr_1fr] items-center gap-2 border-b border-gray-100 px-3.5 py-3 last:border-b-0"
                    >
                      <span className="text-[13.5px] text-gray-900">
                        {observationLabel(observation, t)}
                      </span>
                      <span
                        className={cn(
                          "font-mono text-sm font-bold",
                          flagged ? "text-warning-700" : "text-gray-900",
                        )}
                      >
                        {observationValueLabel(observation)}
                        {observation.value?.unit?.display && (
                          <span className="ml-1 font-sans text-[11px] font-normal text-gray-500">
                            {observation.value.unit.display}
                          </span>
                        )}
                      </span>
                      <span className="text-right text-[11.5px] text-gray-600">
                        {reference ??
                          observation.interpretation?.display ??
                          "-"}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}

            {report.conclusion && (
              <div className="flex flex-col gap-1.5 rounded-2xl border border-gray-200 bg-gray-50 p-4">
                <span className="text-[13px] font-bold text-gray-900">
                  {t("conclusion")}
                </span>
                <span className="text-[12.5px] leading-relaxed text-gray-600">
                  {report.conclusion}
                </span>
              </div>
            )}

            {report.note && (
              <p className="text-[12.5px] leading-relaxed text-gray-600">
                {report.note}
              </p>
            )}

            <div className="rounded-2xl border border-gray-200 bg-gray-50 px-3.5 py-3">
              <span className="text-xs text-gray-600">
                {t("patient_records__verified_by")}{" "}
                <span className="font-semibold text-gray-900">
                  {formatName(report.updated_by ?? report.created_by)}
                </span>
              </span>
            </div>
          </>
        )}
      </div>
    </PatientAppShell>
  );
}

