                {resourceName}
              </DetailRow>
              <DetailRow label={t("date")}>
                {start.format("ddd, D MMM YYYY · h:mm A")}
              </DetailRow>
              <DetailRow label={t("facility")}>
                {appointment.facility.name}
              </DetailRow>
              <DetailRow label={t("status")}>
                {t(appointment.status)}
              </DetailRow>
            </div>
