                {t("patient_booking__arrive_early_heading")}
              </span>
              <span className="text-[12.5px] leading-relaxed text-gray-600">
                {t("patient_booking__arrive_early_description")}
              </span>
            </div>
          </div>

          <Button variant="secondary" size="lg" className="h-12" asChild>
