import {
  ArrowLeft,
  CalendarDays,
  Check,
  ChevronDown,
  FolderClosed,
  Home,
  User,
} from "lucide-react";
import { Link, navigate, usePath } from "raviger";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Avatar } from "@/components/Common/Avatar";
import { PatientSwitcherSheet } from "@/components/Patient/PatientSwitcherSheet";

import { usePatientContext } from "@/hooks/usePatientUser";

/** How long the "now showing records for X" confirmation stays up. */
const SWITCH_NOTICE_MS = 4000;

const TABS = [
  { key: "home", href: "/patient/home", icon: Home, label: "home" },
  {
    key: "visits",
    href: "/patient/visits",
    icon: CalendarDays,
    label: "visits",
  },
  {
    key: "records",
    href: "/patient/records",
    icon: FolderClosed,
    label: "records",
  },
  { key: "profile", href: "/patient/profile", icon: User, label: "profile" },
] as const;

/** `Anitha Ravindran` → `Anitha R.` so the header chip stays on one line. */
function abbreviateName(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length < 2) {
    return parts[0] ?? "";
  }
  return `${parts[0]} ${parts[parts.length - 1][0]}.`;
}

interface PatientAppShellProps {
  children: React.ReactNode;
  /**
   * Omit on the home screen to get the large "Viewing <patient>" chip.
   * Provide it elsewhere to get a page title alongside a compact chip.
   */
  title?: string;
  /** Renders a back affordance instead of the tab bar's implicit navigation. */
  backTo?: string;
  /** Detail screens hide the tab bar so the page owns the full height. */
  hideTabs?: boolean;
  /** Trailing header content, e.g. a download action on detail screens. */
  headerAction?: React.ReactNode;
}

export function PatientAppShell({
  children,
  title,
  backTo,
  hideTabs,
  headerAction,
}: PatientAppShellProps) {
  const { t } = useTranslation();
  const path = usePath();
  const { selectedPatient, patients } = usePatientContext();

  const [switcherOpen, setSwitcherOpen] = useState(false);
  const [switchedTo, setSwitchedTo] = useState<string | null>(null);

  useEffect(() => {
    if (!switchedTo) {
      return;
    }
    const timer = setTimeout(() => setSwitchedTo(null), SWITCH_NOTICE_MS);
    return () => clearTimeout(timer);
  }, [switchedTo]);

  const canSwitch = (patients?.length ?? 0) > 1;

  const switcherChip = selectedPatient && (
    <button
      type="button"
      onClick={() => setSwitcherOpen(true)}
      disabled={!canSwitch}
      className={cn(
        "flex items-center gap-2 rounded-full border border-gray-200 bg-gray-50 py-1 pl-1 pr-3",
        canSwitch && "hover:border-gray-300",
      )}
    >
      <Avatar
        name={selectedPatient.name}
        className={cn("rounded-full", title ? "size-6" : "size-7")}
      />
      {title ? (
        <span className="text-[13px] font-semibold text-gray-900">
          {abbreviateName(selectedPatient.name)}
        </span>
      ) : (
        <span className="flex flex-col items-start leading-tight">
          <span className="text-[9.5px] font-bold uppercase tracking-wider text-gray-500">
            {t("patient_shell__viewing")}
          </span>
          <span className="text-sm font-bold text-gray-900">
            {abbreviateName(selectedPatient.name)}
          </span>
        </span>
      )}
      {canSwitch && <ChevronDown className="size-3.5 text-gray-500" />}
    </button>
  );

  const tabBar = (orientation: "horizontal" | "vertical") => (
    <>
      {TABS.map((tab) => {
        const isActive = path?.startsWith(tab.href);
        const Icon = tab.icon;
        return (
          <Link
            key={tab.key}
            href={tab.href}
            className={cn(
              "flex items-center justify-center gap-1 transition-colors",
              orientation === "horizontal"
                ? "flex-col py-1"
                : "w-full flex-col rounded-xl py-3",
              isActive
                ? "text-primary-700"
                : "text-gray-400 hover:text-gray-600",
              orientation === "vertical" && isActive && "bg-primary-50",
            )}
            aria-current={isActive ? "page" : undefined}
          >
            <Icon className="size-5" strokeWidth={1.9} />
            <span
              className={cn(
                "text-[10.5px]",
                isActive ? "font-bold" : "font-semibold",
              )}
            >
              {t(tab.label)}
            </span>
          </Link>
        );
      })}
    </>
  );

  return (
    <div className="flex min-h-dvh bg-gray-100">
      {!hideTabs && (
        <nav
          aria-label={t("patient_shell__navigation")}
          className="sticky top-0 hidden h-dvh w-24 shrink-0 flex-col gap-1 border-r border-gray-200 bg-white p-3 md:flex"
        >
          {tabBar("vertical")}
        </nav>
      )}

      <div className="flex flex-1 justify-center">
        <div className="flex w-full max-w-[480px] flex-col bg-gray-50 md:my-4 md:min-h-0 md:rounded-3xl md:border md:border-gray-200 md:shadow-sm">
          <header className="sticky top-0 z-10 shrink-0 border-b border-gray-200 bg-white md:rounded-t-3xl">
            <div className="flex items-center gap-2.5 px-4 py-3">
              {backTo && (
                <button
                  type="button"
                  onClick={() => navigate(backTo)}
                  aria-label={t("back")}
                  className="-ml-1 flex size-8 items-center justify-center rounded-lg text-gray-900 hover:bg-gray-100"
                >
                  <ArrowLeft className="size-5" strokeWidth={1.9} />
                </button>
              )}
              {title && (
                <h1 className="truncate text-lg font-bold tracking-tight text-gray-900">
                  {title}
                </h1>
              )}
              <div className="ml-auto flex items-center gap-2">
                {headerAction}
                {!hideTabs && switcherChip}
              </div>
            </div>
          </header>

          {switchedTo && (
            <div className="mx-4 mt-3 flex items-center gap-2.5 rounded-xl border border-primary-200 bg-primary-50 px-3.5 py-2.5">
              <Check className="size-4 text-primary-700" strokeWidth={2.4} />
              <span className="text-[12.5px] font-semibold text-primary-800">
                {t("patient_shell__now_showing", { name: switchedTo })}
              </span>
            </div>
          )}

          <main className="flex flex-1 flex-col">{children}</main>

          {!hideTabs && (
            <nav
              aria-label={t("patient_shell__navigation")}
              className="sticky bottom-0 grid shrink-0 grid-cols-4 border-t border-gray-200 bg-white px-2 pb-5 pt-2 md:hidden"
            >
              {tabBar("horizontal")}
            </nav>
          )}
        </div>
      </div>

      <PatientSwitcherSheet
        open={switcherOpen}
        onOpenChange={setSwitcherOpen}
        onSwitched={(patient) => setSwitchedTo(patient.name)}
      />
    </div>
  );
}

import careConfig from "@careConfig";
import dayjs from "dayjs";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { AlertCircle, Lock } from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import { PhoneInput } from "@/components/ui/phone-input";

import CircularProgress from "@/components/Common/CircularProgress";

import { useAuthContext } from "@/hooks/useAuthUser";
import { usePatientOtpLogin } from "@/hooks/usePatientOtpLogin";

import PatientAuthLayout from "./PatientAuthLayout";

/** Tokens are minted for 15 minutes; re-use one that still has life in it. */
const TOKEN_FRESHNESS_MINUTES = 14;

const formatCountdown = (seconds: number) =>
  `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(
    seconds % 60,
  ).padStart(2, "0")}`;

interface PatientLoginProps {
  /** Where to land after a successful verification. */
  redirectTo?: string;
}

export default function PatientLogin({ redirectTo }: PatientLoginProps) {
  const { t } = useTranslation();
  const { patientToken } = useAuthContext();
  const [hasConsented, setHasConsented] = useState(false);

  const {
    otpLength,
    phone,
    otp,
    isOtpSent,
    phoneError,
    otpError,
    countdown,
    isSendingOtp,
    isVerifyingOtp,
    isPhoneValid,
    isOtpComplete,
    updatePhone,
    updateOtp,
    sendOtp,
    resendOtp,
    verifyOtp,
    changePhoneNumber,
  } = usePatientOtpLogin({ redirectTo });

  const hasFreshToken =
    !!patientToken?.token &&
    dayjs(patientToken.createdAt).isAfter(
      dayjs().subtract(TOKEN_FRESHNESS_MINUTES, "minutes"),
    );

  useEffect(() => {
    if (hasFreshToken) {
      navigate(redirectTo ?? "/patient/select-profile");
    }
  }, [hasFreshToken, redirectTo]);

  if (isOtpSent) {
    return (
      <PatientAuthLayout onBack={changePhoneNumber}>
        <h1 className="text-2xl font-bold tracking-tight text-gray-900">
          {t("patient_login__otp_heading")}
        </h1>
        <p className="mt-2.5 text-[15px] leading-relaxed text-gray-600">
          {t("patient_login__otp_sent_to", { phone })}
          {" · "}
          <button
            type="button"
            onClick={changePhoneNumber}
            className="font-semibold text-primary-700 hover:underline"
          >
            {t("patient_login__change_number")}
          </button>
        </p>

        <form
          className="mt-9"
          onSubmit={(event) => {
            event.preventDefault();
            verifyOtp();
          }}
        >
          <InputOTP
            value={otp}
            onChange={updateOtp}
            maxLength={otpLength}
            pattern={REGEXP_ONLY_DIGITS}
            autoComplete="one-time-code"
            autoFocus
            containerClassName="gap-2.5"
            aria-label={t("enter_otp")}
            aria-invalid={!!otpError}
          >
            {Array.from({ length: otpLength }).map((_, index) => (
              <InputOTPGroup key={index} className="flex-1">
                <InputOTPSlot
                  index={index}
                  className={cn(
                    "h-14 w-full rounded-xl! border! text-2xl font-bold",
                    otpError
                      ? "border-red-500! text-red-600"
                      : "border-gray-300!",
                  )}
                />
              </InputOTPGroup>
            ))}
          </InputOTP>

          {otpError && (
            <div className="mt-3.5 flex items-start gap-2.5 text-red-600">
              <AlertCircle className="mt-0.5 size-4 shrink-0" />
              <p className="text-[13px] font-semibold leading-snug">
                {t(otpError)}
              </p>
            </div>
          )}

          <div className="mt-5 flex items-center justify-between">
            {countdown > 0 ? (
              <>
                <span className="text-[13.5px] text-gray-600">
                  {t("patient_login__resend_in")}{" "}
                  <span className="font-mono font-bold text-gray-900">
                    {formatCountdown(countdown)}
                  </span>
                </span>
                <span className="text-[13.5px] font-semibold text-gray-400">
                  {t("resend_otp")}
                </span>
              </>
            ) : (
              <>
                <span className="text-[13.5px] text-gray-600">
                  {t("didnt_receive_a_message")}
                </span>
                <button
                  type="button"
                  onClick={resendOtp}
                  disabled={isSendingOtp}
                  className="text-[13.5px] font-bold text-primary-700 hover:underline disabled:opacity-50"
                >
                  {t("resend_otp")}
                </button>
              </>
            )}
          </div>

          <Button
            type="submit"
            size="lg"
            className="mt-8 h-12 w-full text-base"
            disabled={!isOtpComplete || isVerifyingOtp}
          >
            {isVerifyingOtp ? (
              <CircularProgress className="text-white" />
            ) : (
              t("patient_login__verify_continue")
            )}
          </Button>
        </form>

        <div className="mt-6 flex gap-2.5 rounded-lg border border-gray-200 bg-gray-50 p-3.5">
          <Lock className="mt-0.5 size-4 shrink-0 text-primary-700" />
          <p className="text-[12.5px] leading-snug text-gray-600">
            {t("patient_login__otp_security_note")}
          </p>
        </div>
      </PatientAuthLayout>
    );
  }

  return (
    <PatientAuthLayout
      showLogo
      footer={
        careConfig.patientSupportPhone && (
          <p className="text-center text-[13px] text-gray-600">
            {t("patient_login__helpline")}{" "}
            <a
              href={`tel:${careConfig.patientSupportPhone}`}
              className="font-semibold text-primary-700 hover:underline"
            >
              {careConfig.patientSupportPhone}
            </a>
          </p>
        )
      }
    >
      <h1 className="text-[28px] font-bold leading-tight tracking-tight text-gray-900">
        {t("patient_login__heading")}
      </h1>
      <p className="mt-2.5 text-[15px] leading-relaxed text-gray-600">
        {t("patient_login__subheading", { length: otpLength })}
      </p>

      <form
        className="mt-8"
        onSubmit={(event) => {
          event.preventDefault();
          sendOtp();
        }}
      >
        <Label htmlFor="patient-login-phone" className="mb-2 block text-[13px]">
          {t("phone_number")}
        </Label>
        <PhoneInput
          id="patient-login-phone"
          value={phone}
          onChange={updatePhone}
          placeholder={t("enter_phone_number")}
          disabled={isSendingOtp}
          autoFocus
        />
        {phoneError && (
          <p className="mt-2 text-sm text-red-500">{t(phoneError)}</p>
