          />
          <span className="text-[12.5px] leading-snug text-gray-600">
            {t("patient_login__consent")}
          </span>
        </label>

        <Button
          type="submit"
          size="lg"
          className="mt-7 h-12 w-full text-base"
          disabled={!isPhoneValid || !hasConsented || isSendingOtp}
        >
          {isSendingOtp ? (
            <CircularProgress className="text-white" />
          ) : (
            t("send_otp")
          )}
        </Button>
      </form>
    </PatientAuthLayout>
  );
}

