    return b.textContent.replace(/\s+/g,' ').trim().slice(0,45)+' | pressed='+b.getAttribute('aria-pressed');
  });
  return JSON.stringify({rows:rows, stored: localStorage.getItem('care_selected_patient'), overflow: d.scrollWidth>d.clientWidth+1});
})()

