70	        .string()
71	        .min(1, t("field_required"))
72	        .refine(validateName, t("min_char_length_error", { min_length: 3 })),
73	      gender: z.enum(GENDERS, { error: t("gender_is_required") }),
74	      address: z.string().min(1, t("field_required")),
75	      age: z.string().optional(),
76	      date_of_birth: z.date().or(z.string()).optional(),
77	      pincode: validators().pincode,
78	      geo_organization: z.string().min(1, t("organization_required")),
79	      ageInputType: z.enum(["age", "date_of_birth"]),
80	    })
81	    .superRefine((data, ctx) => {
82	      const field = data.ageInputType === "age" ? "age" : "date_of_birth";
83	      if (!data[field]) {
84	        ctx.addIssue({
