python3 - <<'PY'
p="src/pages/PublicAppointments/Schedule.tsx"
s=open(p).read()

old = """              {/* PatientSelect books the appointment itself, so it needs the
                  slot and reason carried across. */}
              <Link
                href={`/facility/${facilityId}/appointments/${staffId}/patient-select`}
                query={{ slotId: selectedSlot?.id ?? "", reason }}
                className="shrink-0 text-[13px] font-semibold text-primary-700"
              >
                {t("change")}
              </Link>"""
new = """              {/* Switching happens in place via the shared sheet — the old
                  patient-select page is gone. */}
              <button
                type="button"
                onClick={() => setSwitcherOpen(true)}
                className="shrink-0 text-[13px] font-semibold text-primary-700"
              >
                {t("change")}
              </button>"""
assert s.count(old)==1, "change link"
s=s.replace(old,new)

# state + sheet
s=s.replace("""  const [reasonDraft, setReasonDraft] = useState<string>();""",
"""  const [reasonDraft, setReasonDraft] = useState<string>();
  const [switcherOpen, setSwitcherOpen] = useState(false);""")

s=s.replace('import { Avatar } from "@/components/Common/Avatar";',
            'import { Avatar } from "@/components/Common/Avatar";\nimport { PatientSwitcherSheet } from "@/components/Patient/PatientSwitcherSheet";')

# render the sheet inside the reason step
old_reason_end = """        </div>
      </BookingStepLayout>
    );
  }"""
new_reason_end = """        </div>

        <PatientSwitcherSheet
          open={switcherOpen}
          onOpenChange={setSwitcherOpen}
        />
      </BookingStepLayout>
    );
  }"""
assert s.count(old_reason_end)==1, "reason end"
s=s.replace(old_reason_end,new_reason_end)
open(p,"w").write(s)
print("Schedule.tsx now uses the switcher sheet")
PY
