export default function PublicRouter() {
  const routeResult = useRoutes(routes);
  const path = usePath();

  // A signed-out visitor deep-linking into the patient app (`/patient/home`,
  // `/patient/records`, …) matches nothing here. Falling through to the staff
  // login would show the wrong form and leave the patient URL in the address
  // bar, so send them to the patient login instead.
  const isPatientPath =
    !!path && path.startsWith("/patient") && path !== "/patient/login";

  return (
    <>
      <BrowserWarning />
      {routeResult ||
        (isPatientPath ? <Redirect to="/patient/login" /> : <Login />)}
    </>
  );
}

