83	      onSuccess: () => {
84	        toast.success(t("password_sent"));
85	      },
86	    });
87	
88	  // Login form validation
89	  const handleChange = (e: any) => {
90	    const { value, name } = e.target;
91	    const fieldValue = Object.assign({}, form);
92	    const errorField = Object.assign({}, errors);
93	    if (errorField[name]) {
94	      errorField[name] = null;
95	      setErrors(errorField);
96	    }
97	    fieldValue[name] = value;
98	    if (name === "username") {
99	      fieldValue[name] = value.toLowerCase();
100	    }
101	    setForm(fieldValue);
102	  };
