104	  const validateData = () => {
105	    let hasError = false;
106	    const err = Object.assign({}, errors);
107	    Object.keys(form).forEach((key) => {
108	      if (
109	        typeof form[key] === "string" &&
110	        key !== "password" &&
111	        key !== "confirm"
112	      ) {
