(function(){
  var els=[...document.querySelectorAll('*')].slice(0,800);
  var fonts=[...new Set(els.map(e=>getComputedStyle(e).fontFamily))];
  var sizes={}, radii={}, weights={};
  els.forEach(function(e){
    var s=getComputedStyle(e);
    if(e.textContent && e.children.length===0){ sizes[s.fontSize]=(sizes[s.fontSize]||0)+1; weights[s.fontWeight]=(weights[s.fontWeight]||0)+1; }
    if(s.borderRadius && s.borderRadius!=='0px') radii[s.borderRadius]=(radii[s.borderRadius]||0)+1;
  });
  var colors=[...new Set(els.flatMap(e=>[getComputedStyle(e).color]).filter(c=>c!=='rgba(0, 0, 0, 0)'))];
  var small=[...document.querySelectorAll('a,button,input,[role=button],[role=tab],[role=checkbox]')].filter(function(e){var r=e.getBoundingClientRect(); return r.width>0 && (r.width<44||r.height<44);}).map(function(e){var r=e.getBoundingClientRect(); return (e.textContent||e.tagName).trim().slice(0,24)+' '+Math.round(r.width)+'x'+Math.round(r.height);});
  return JSON.stringify({fonts:fonts, fontSizes:sizes, fontWeights:weights, radii:radii, textColorCount:colors.length, undersizedTargets:small}, null, 1);
})()

(function(){
  var small=[...document.querySelectorAll('a,button,[role=button],[role=tab]')].filter(function(e){var r=e.getBoundingClientRect(); return r.width>0 && r.height<44;}).map(function(e){var r=e.getBoundingClientRect(); return {t:(e.textContent||'').trim().slice(0,22)||e.tagName, h:Math.round(r.height), w:Math.round(r.width), cls:(e.className||'').toString().slice(0,50)};});
  return JSON.stringify(small,null,1);
})()

