(function(){
  var d=document.documentElement;
  var small=[...document.querySelectorAll('a,button,[role=button],[role=tab]')].filter(function(e){var r=e.getBoundingClientRect(); return r.width>0 && r.height<44;}).map(function(e){var r=e.getBoundingClientRect(); return (e.textContent||'').trim().slice(0,26)+' → '+Math.round(r.height)+'px';});
  var sizes={};
  [...document.querySelectorAll('*')].slice(0,800).forEach(function(e){ if(e.textContent&&e.children.length===0){var s=getComputedStyle(e).fontSize; sizes[s]=(sizes[s]||0)+1;} });
  return JSON.stringify({overflow: d.scrollWidth>d.clientWidth+1, distinctFontSizes: Object.keys(sizes).length, sizes:sizes, undersized: small},null,1);
})()
